import React from "react";
import { FaBolt, FaUserGraduate, FaLeaf } from "react-icons/fa";

const Projects = () => {
  return (
    <section className="projects">

      {/* HEADER */}
      <div className="header">
        <h1>Projects</h1>
        <p>Structured applications built with focus on UI clarity and system design</p>
      </div>

      {/* GRID */}
      <div className="grid">

        {/* COGNI FLOW */}
        <div className="row">
          <div className="left">
            <FaBolt className="icon" />
            <h2>Cogni Flow</h2>
            <span>HTML • CSS • JavaScript</span>
          </div>

          <div className="right">
            <p>
              A structured workflow system designed to simplify task flow,
              improve clarity, and enhance productivity using clean UI logic
              and interactive frontend design.
            </p>
          </div>
        </div>

        {/* ENERGY PULSE */}
        <div className="row">
          <div className="left">
            <FaBolt className="icon" />
            <h2>EnergyPulse</h2>
            <span>React.js</span>
          </div>

          <div className="right">
            <p>
              AI-powered smart home dashboard frontend that visualizes real-time
              biometric and energy data with a responsive and intuitive UI system.
            </p>
          </div>
        </div>

        {/* STUDENT PORTAL */}
        <div className="row">
          <div className="left">
            <FaUserGraduate className="icon" />
            <h2>Student Portal Management</h2>
            <span>Spring Boot • MySQL • Web Stack</span>
          </div>

          <div className="right">
            <p>
              Full-stack academic management system with structured backend APIs
              and a clean frontend interface for handling student records efficiently.
            </p>
          </div>
        </div>

        {/* FARM2FORK */}
        <div className="row">
          <div className="left">
            <FaLeaf className="icon" />
            <h2>Farm2Fork</h2>
            <span>HTML • CSS • JavaScript</span>
          </div>

          <div className="right">
            <p>
              Responsive marketplace platform connecting farmers and consumers
              with smooth product browsing and simple UI navigation flow.
            </p>
          </div>
        </div>

      </div>

      {/* STYLE */}
      <style>{`

        .projects {
          min-height: 100vh;
          padding: 50px 10%;
          background: radial-gradient(circle at top, #0b1220, #050816);
          color: white;
          font-family: "Poppins", sans-serif;
        }

        /* HEADER */
        .header {
          text-align: center;
          margin-bottom: 50px;
        }

        .header h1 {
          font-size: 40px;
          color: #e2e8f0;
        }

        .header p {
          color: #94a3b8;
          margin-top: 8px;
        }

        /* GRID */
        .grid {
          display: flex;
          flex-direction: column;
          gap: 25px;
        }

        /* ROW LAYOUT */
        .row {
          display: grid;
          grid-template-columns: 1fr 2fr;
          gap: 30px;
          padding: 20px;
          border-radius: 14px;
          background: rgba(255,255,255,0.03);
          border: 1px solid rgba(56,189,248,0.15);
          transition: 0.3s;
        }

        .row:hover {
          transform: translateY(-4px);
          border-color: #38BDF8;
        }

        /* LEFT */
        .left {
          display: flex;
          flex-direction: column;
          gap: 6px;
        }

        .icon {
          color: #38BDF8;
          font-size: 20px;
        }

        .left h2 {
          margin: 0;
          color: #38BDF8;
          font-size: 18px;
        }

        .left span {
          font-size: 12px;
          color: #94a3b8;
        }

        /* RIGHT */
        .right p {
          color: #cbd5e1;
          line-height: 1.7;
        }

        /* RESPONSIVE */
        @media (max-width: 900px) {
          .row {
            grid-template-columns: 1fr;
          }
        }

      `}</style>

    </section>
  );
};

export default Projects;
